CREATE TYPE "TicketStatus" AS ENUM ('PENDING','VALID','WINNER','LOSER','CANCELLED','VOID','PAID','EXPIRED');
CREATE TYPE "TicketEventType" AS ENUM ('CREATED','PRINTED','REPRINTED','CANCEL_REQUESTED','CANCELLED','RESULT_CHECKED','MARKED_WINNER','MARKED_LOSER','PAID','VOIDED');
CREATE TYPE "LedgerTransactionType" AS ENUM ('SALE','COMMISSION','PAYOUT','CASH_IN','CASH_OUT','ADJUSTMENT');
CREATE TYPE "LedgerStatus" AS ENUM ('POSTED','REVERSED');
CREATE TABLE "Ticket" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"ticketNumber" VARCHAR(80) NOT NULL,"idempotencyKey" VARCHAR(100) NOT NULL,"branchId" UUID NOT NULL REFERENCES "Branch"("id") ON DELETE RESTRICT,"merchantId" UUID NOT NULL REFERENCES "MerchantAccount"("id") ON DELETE RESTRICT,"deviceId" UUID,"gameId" UUID NOT NULL REFERENCES "Game"("id") ON DELETE RESTRICT,"drawId" UUID NOT NULL REFERENCES "Draw"("id") ON DELETE RESTRICT,"amount" NUMERIC(19,4) NOT NULL,"commission" NUMERIC(19,4) NOT NULL DEFAULT 0,"potentialWin" NUMERIC(19,4) NOT NULL,"status" "TicketStatus" NOT NULL DEFAULT 'VALID',"barcode" VARCHAR(180) NOT NULL UNIQUE,"qrCode" VARCHAR(500) NOT NULL UNIQUE,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("tenantId","ticketNumber"),UNIQUE("tenantId","idempotencyKey"),CHECK("amount">0),CHECK("potentialWin">=0));
CREATE TABLE "TicketLine" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"ticketId" UUID NOT NULL REFERENCES "Ticket"("id") ON DELETE RESTRICT,"betTypeId" UUID NOT NULL REFERENCES "BetType"("id") ON DELETE RESTRICT,"selection" JSONB NOT NULL,"selectionKey" VARCHAR(120) NOT NULL,"stake" NUMERIC(19,4) NOT NULL,"odds" NUMERIC(19,6) NOT NULL,"potentialWin" NUMERIC(19,4) NOT NULL,"isWinner" BOOLEAN,CHECK("stake">0),CHECK("odds">0));
CREATE TABLE "TicketEvent" ("id" BIGSERIAL PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"ticketId" UUID NOT NULL REFERENCES "Ticket"("id") ON DELETE RESTRICT,"type" "TicketEventType" NOT NULL,"userId" UUID REFERENCES "User"("id") ON DELETE SET NULL,"deviceId" UUID,"ipAddress" INET,"metadata" JSONB,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "WinningTicket" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"ticketId" UUID NOT NULL UNIQUE REFERENCES "Ticket"("id") ON DELETE RESTRICT,"winningAmount" NUMERIC(19,4) NOT NULL,"detectedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE "LedgerAccount" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"code" VARCHAR(60) NOT NULL,"name" VARCHAR(160) NOT NULL,"type" VARCHAR(30) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,UNIQUE("tenantId","code"));
CREATE TABLE "LedgerTransaction" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"type" "LedgerTransactionType" NOT NULL,"referenceType" VARCHAR(60) NOT NULL,"referenceId" VARCHAR(100) NOT NULL,"idempotencyKey" VARCHAR(100) NOT NULL,"status" "LedgerStatus" NOT NULL DEFAULT 'POSTED',"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("tenantId","idempotencyKey"));
CREATE TABLE "LedgerEntry" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"transactionId" UUID NOT NULL REFERENCES "LedgerTransaction"("id") ON DELETE RESTRICT,"accountId" UUID NOT NULL REFERENCES "LedgerAccount"("id") ON DELETE RESTRICT,"debit" NUMERIC(19,4) NOT NULL DEFAULT 0,"credit" NUMERIC(19,4) NOT NULL DEFAULT 0,CHECK(("debit">0 AND "credit"=0) OR ("credit">0 AND "debit"=0)));
CREATE TABLE "Payout" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"ticketId" UUID NOT NULL UNIQUE REFERENCES "Ticket"("id") ON DELETE RESTRICT,"amount" NUMERIC(19,4) NOT NULL,"authorizedById" UUID NOT NULL REFERENCES "User"("id") ON DELETE RESTRICT,"idempotencyKey" VARCHAR(100) NOT NULL,"ledgerTransactionId" UUID NOT NULL UNIQUE REFERENCES "LedgerTransaction"("id") ON DELETE RESTRICT,"paidAt" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("tenantId","idempotencyKey"));
CREATE INDEX "ticket_tenant_time" ON "Ticket"("tenantId","createdAt" DESC);CREATE INDEX "ticket_draw_status" ON "Ticket"("drawId","status");CREATE INDEX "ticket_merchant_time" ON "Ticket"("merchantId","createdAt" DESC);CREATE INDEX "line_ticket" ON "TicketLine"("tenantId","ticketId");CREATE INDEX "line_selection" ON "TicketLine"("tenantId","selectionKey");CREATE INDEX "event_ticket_time" ON "TicketEvent"("tenantId","ticketId","createdAt");CREATE INDEX "ledger_tenant_time" ON "LedgerTransaction"("tenantId","createdAt" DESC);
ALTER TABLE "Ticket" ENABLE ROW LEVEL SECURITY;ALTER TABLE "TicketLine" ENABLE ROW LEVEL SECURITY;ALTER TABLE "TicketEvent" ENABLE ROW LEVEL SECURITY;ALTER TABLE "WinningTicket" ENABLE ROW LEVEL SECURITY;ALTER TABLE "Payout" ENABLE ROW LEVEL SECURITY;ALTER TABLE "LedgerAccount" ENABLE ROW LEVEL SECURITY;ALTER TABLE "LedgerTransaction" ENABLE ROW LEVEL SECURITY;ALTER TABLE "LedgerEntry" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_ticket_isolation ON "Ticket" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_line_isolation ON "TicketLine" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_event_isolation ON "TicketEvent" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_winner_isolation ON "WinningTicket" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_payout_isolation ON "Payout" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_account_isolation ON "LedgerAccount" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_ledger_tx_isolation ON "LedgerTransaction" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_ledger_entry_isolation ON "LedgerEntry" USING ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK ("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
